insert into public.questions
(exam_category, subject, topic, type, difficulty, body, question_data, options, marks_correct, marks_wrong, explanation, concept_group_id, source_type, source_citation, status)
values
('upsc','Environment & Ecology','Fauna & Animal Behaviour','statement_based','medium','Consider the following statements about the Nilgiri tahr:','{"statements": ["It is chiefly a browser of dense evergreen forest interiors and avoids open grassland.", "Eravikulam National Park in Kerala holds the largest single population of the species.", "It is endemic to the Western Ghats and is the State animal of Tamil Nadu."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": true}, {"id": "c", "body": "All three", "isCorrect": false}, {"id": "d", "body": "None", "isCorrect": false}]'::jsonb,2,0.66,'Only statements 2 and 3 are correct. The Nilgiri tahr lives on the open montane grasslands and rocky cliffs of the southern Western Ghats, roughly 1,200-2,600 m up, and grazes on grasses -- it is not a forest-interior browser, which is the planted habitat swap in statement 1. Eravikulam National Park near Munnar holds the largest single population. The species is endemic to the Western Ghats, is Tamil Nadu''s State animal, is listed as Endangered by the IUCN and is in Schedule I of the Wildlife (Protection) Act, 1972.','env-nilgiri-tahr-habitat','original_pattern_matched','WWF-India, ''Nilgiri tahr'' (priority species); Kerala Forest Department, Eravikulam National Park; IUCN Red List, Nilgiritragus hylocrius.','draft'),
('upsc','Environment & Ecology','Pollution, Waste & Resources','statement_based','medium','Consider the following statements about ground-level (tropospheric) ozone:','{"statements": ["It is not emitted directly in significant quantities; it forms when oxides of nitrogen and volatile organic compounds react in the presence of sunlight.", "Because its formation is driven by sunlight and heat, it tends to reach its highest levels on hot, sunny days.", "It is one of the twelve pollutants covered by India''s National Ambient Air Quality Standards notified in 2009."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": false}, {"id": "c", "body": "All three", "isCorrect": true}, {"id": "d", "body": "None", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. Ground-level ozone is a secondary pollutant: vehicles, power plants and industry emit its precursors (NOx and VOCs), and ozone forms from them in sunlight, so levels build up on hot, sunny days and it is mainly a summertime pollutant. Being secondary does not keep it out of regulation: the National Ambient Air Quality Standards, 2009 cover twelve pollutants, including ozone (8-hour and 1-hour limits), alongside SO2, NO2, PM10, PM2.5, CO, lead, ammonia, benzene, benzo(a)pyrene, arsenic and nickel. Do not confuse it with the stratospheric ozone layer, which is protective.','env-ground-level-ozone','original_pattern_matched','US EPA, ''Ground-level Ozone Basics''; CPCB, National Ambient Air Quality Standards (notification of 18 November 2009).','draft'),
('upsc','Environment & Ecology','Climate Science & Mitigation','statement_based','medium','Consider the following statements about global warming potential (GWP):','{"statements": ["On a 100-year time horizon, nitrous oxide has a higher global warming potential than methane.", "Methane''s global warming potential is lower on a 20-year horizon than on a 100-year horizon, because methane stays in the atmosphere for several centuries."], "closing": "Which of the statements given above is/are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "isCorrect": true}, {"id": "b", "body": "2 only", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. GWP compares the warming caused by a gas over a chosen period with that of the same mass of CO2 (GWP = 1). In IPCC AR6 the 100-year GWP of nitrous oxide is 273, against about 27-30 for methane. Statement 2 is wrong on both counts: methane lasts only about 12 years in the atmosphere, so its effect is concentrated early -- its 20-year GWP (about 81) is far higher than its 100-year GWP, which is why cutting methane is seen as the fastest lever on near-term warming.','env-gwp-methane-n2o','original_pattern_matched','IPCC AR6 Working Group I, Chapter 7, Table 7.15 (emission metrics).','draft'),
('upsc','Environment & Ecology','Flora, Fungi & Forests','statement_based','medium','Consider the following statements about mangroves:','{"statements": ["Pneumatophores are aerial roots that help mangrove plants take in oxygen in waterlogged, oxygen-poor mud.", "In viviparous mangroves, the seed germinates while the fruit is still attached to the parent tree.", "In India, mangroves occur only along the eastern coast and in the Andaman and Nicobar Islands."], "closing": "Which of the statements given above is/are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "isCorrect": false}, {"id": "b", "body": "1 and 2 only", "isCorrect": true}, {"id": "c", "body": "2 and 3 only", "isCorrect": false}, {"id": "d", "body": "1, 2 and 3", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. Pneumatophores (breathing roots) rise above the mud to take in air, and vivipary -- germination while still on the parent tree -- lets the seedling establish quickly in tidal mud. Statement 3 is wrong: India''s west coast has extensive mangroves, notably in the Gulf of Kutch and Gulf of Khambhat in Gujarat (the State with the second-largest mangrove cover after West Bengal), and along the Maharashtra, Goa, Karnataka and Kerala coasts.','env-mangrove-adaptations','original_pattern_matched','NCERT Class XI, ''India: Physical Environment'', ch. 5 (Natural Vegetation); Forest Survey of India, India State of Forest Report 2021, mangrove cover.','draft'),
('upsc','Environment & Ecology','Climate Agreements & Carbon Markets','statement_based','medium','Consider the following statements regarding Article 6 of the Paris Agreement:','{"statements": ["Under Article 6.2, countries can transfer internationally transferred mitigation outcomes (ITMOs) between themselves through bilateral or cooperative approaches.", "The mechanism under Article 6.4 is supervised by a Supervisory Body, and activities registered under the Kyoto Protocol''s Clean Development Mechanism may transition to it.", "Corresponding adjustments are applied so that a transferred emission reduction is not counted towards the NDCs of both the transferring and the acquiring country.", "India has finalised a list of activities that it would consider for trading carbon credits under Article 6.2."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": false}, {"id": "c", "body": "Only three", "isCorrect": false}, {"id": "d", "body": "All four", "isCorrect": true}]'::jsonb,2,0.66,'All four statements are correct. Article 6.2 lets Parties cooperate bilaterally and count ITMOs towards their NDCs; Article 6.4 sets up a UN-run crediting mechanism (the Paris Agreement Crediting Mechanism), run by the Article 6.4 Supervisory Body, into which CDM activities may transition. Corresponding adjustments prevent the same reduction being counted twice. In February 2023 India finalised 13 activities under three heads -- GHG mitigation, alternate materials and removals -- that it would consider for Article 6.2 trading, such as green hydrogen, offshore wind and tidal energy.','env-paris-article6','original_pattern_matched','UNFCCC, ''Article 6 of the Paris Agreement'' and ''Article 6.4 Supervisory Body''; PIB, MoEFCC release of 17 February 2023 (Article 6.2 activities).','draft')
